#!/usr/bin/env python3
"""Compute deterministic timing-ledger ground truth for CSX-239_Q2."""

from __future__ import annotations

import html
import json
import re
from datetime import datetime, timedelta
from pathlib import Path
from typing import Any


TASK_ID = "CSX-239_Q2"
PACKAGE_ID = "CSX-239"



REASONING_DEPTH = {'evidence_weighting': 'GDACS origin time and USGS lag text are decisive for arrival windows; GPM precipitation is an exclusion check against rainfall-driven timing.', 'counterfactual_rejection': 'A rainfall-flood timing explanation fails because the rounded GPM mean is below 1 mm while the report supplies coherent tsunami lag windows.', 'uncertainty_or_scale_caveat': 'The GDACS magnitude is used as the local clock anchor and should not be confused with the USGS magnitude used in broader mechanism discussion.'}


def attach_reasoning_depth(result):
    reasoning = dict(REASONING_DEPTH)
    primary = result.get("primary_gt")
    if isinstance(primary, dict):
        primary["reasoning_depth"] = reasoning
    guidance = result.get("answer_guidance")
    if isinstance(guidance, dict):
        guidance["reasoning_depth"] = reasoning
    key_values = result.get("key_values")
    if isinstance(key_values, dict):
        key_values["reasoning_depth"] = reasoning
    rubric = result.get("rubric")
    if isinstance(rubric, dict):
        criteria = rubric.get("criteria")
        if isinstance(criteria, list) and criteria:
            addition = " Full credit also requires the `reasoning_depth` object to identify decisive evidence, reject the main tempting simplification, and state a bounded uncertainty or scale caveat."
            last = criteria[-1]
            desc = last.get("description", "")
            if addition.strip() not in desc:
                last["description"] = (desc.rstrip() + addition).strip()
    return result

def load_json(package_dir: Path, relative_path: str) -> dict[str, Any]:
    with (package_dir / relative_path).open("r", encoding="utf-8") as handle:
        return json.load(handle)


def read_text(package_dir: Path, relative_path: str) -> str:
    with (package_dir / relative_path).open("r", encoding="utf-8", errors="ignore") as handle:
        return handle.read()


def clean_html_text(raw_html: str) -> str:
    text = re.sub(r"<script\b.*?</script>", " ", raw_html, flags=re.IGNORECASE | re.DOTALL)
    text = re.sub(r"<style\b.*?</style>", " ", text, flags=re.IGNORECASE | re.DOTALL)
    text = re.sub(r"<[^>]+>", " ", text)
    text = html.unescape(text)
    return re.sub(r"\s+", " ", text).strip()


def lag_phrase_to_minutes(phrase: str) -> int:
    normalized = phrase.lower().strip()
    if normalized in {"an hour and a half", "one and a half hours", "1.5 hours"}:
        return 90
    word_hours = {
        "one": 1,
        "two": 2,
        "three": 3,
        "four": 4,
    }
    match = re.fullmatch(r"(one|two|three|four)(?:\s+hours?)?", normalized)
    if match:
        return word_hours[match.group(1)] * 60
    numeric_match = re.fullmatch(r"([0-9]+(?:\.[0-9]+)?)\s*hours?", normalized)
    if numeric_match:
        return int(round(float(numeric_match.group(1)) * 60))
    raise ValueError(f"Unsupported lag phrase: {phrase!r}")


def extract_arrival_lags(text: str) -> dict[str, dict[str, int]]:
    sumatra_match = re.search(
        r"northern Sumatra approximately ([0-9]+) minutes after the earthquake",
        text,
        flags=re.IGNORECASE,
    )
    thailand_match = re.search(
        r"Thailand approximately (an hour and a half) to (two hours) after the earthquake",
        text,
        flags=re.IGNORECASE,
    )
    sri_lanka_match = re.search(
        r"Sri Lanka approximately (two) to (three hours) after the earthquake",
        text,
        flags=re.IGNORECASE,
    )
    if not sumatra_match:
        raise ValueError("Missing northern Sumatra arrival phrase")
    if not thailand_match:
        raise ValueError("Missing Thailand arrival phrase")
    if not sri_lanka_match:
        raise ValueError("Missing Sri Lanka arrival phrase")

    return {
        "northern_sumatra": {"min": int(sumatra_match.group(1)), "max": int(sumatra_match.group(1))},
        "thailand": {
            "min": lag_phrase_to_minutes(thailand_match.group(1)),
            "max": lag_phrase_to_minutes(thailand_match.group(2)),
        },
        "sri_lanka": {
            "min": lag_phrase_to_minutes(sri_lanka_match.group(1)),
            "max": lag_phrase_to_minutes(sri_lanka_match.group(2)),
        },
    }


def gdacs_clock_anchor(gdacs: dict[str, Any]) -> dict[str, Any]:
    features = gdacs.get("features", [])
    eq_features = [feature for feature in features if feature.get("properties", {}).get("eventtype") == "EQ"]
    fl_features = [feature for feature in features if feature.get("properties", {}).get("eventtype") == "FL"]
    red_indonesia_eq = [
        feature
        for feature in eq_features
        if feature.get("properties", {}).get("alertlevel") == "Red"
        and feature.get("properties", {}).get("country") == "Indonesia"
    ]
    if not red_indonesia_eq:
        raise ValueError("Missing Red Indonesia earthquake clock anchor")

    main_feature = max(
        red_indonesia_eq,
        key=lambda feature: float(feature["properties"]["severitydata"]["severity"]),
    )
    props = main_feature["properties"]
    return {
        "eq_count": len(eq_features),
        "fl_count": len(fl_features),
        "eventid": props["eventid"],
        "origin_utc": props["fromdate"],
        "magnitude": float(props["severitydata"]["severity"]),
        "alert": props["alertlevel"],
        "country": props["country"],
    }


def clock_window(origin: datetime, lag_min: int, lag_max: int) -> str:
    start = origin + timedelta(minutes=lag_min)
    end = origin + timedelta(minutes=lag_max)
    return f"{start:%Y-%m-%dT%H:%M:%S}/{end:%Y-%m-%dT%H:%M:%S}"


def main() -> None:
    task_dir = Path(__file__).resolve().parent
    workspace_root = task_dir.parents[2]
    package_dir = workspace_root / "event_packages" / "standard_event_packages" / "packages" / PACKAGE_ID

    metadata_path = "metadata/event.json"
    anchor_path = "data/event_reports/event_reports_002_Locked_event_anchor_2004_Indian_Ocean_tsunami.json"
    report_path = "data/event_reports/event_reports_001_Locked_anchor_USGS_feature.html"
    gdacs_path = "data/event_catalogs/event_catalogs_010_04_event_specific_disaster_catalog_GDACS_event_list_for_package_time_window.json.json"
    gpm_path = "data/physical_hazard/physical_hazard_002_GPM_IMERG_V07_event_accumulated_precipitation.json"
    chirps_path = "data/physical_hazard/physical_hazard_003_CHIRPS_daily_event_accumulated_precipitation.json"

    metadata = load_json(package_dir, metadata_path)
    anchor = load_json(package_dir, anchor_path)
    gdacs = load_json(package_dir, gdacs_path)
    gpm = load_json(package_dir, gpm_path)
    chirps = load_json(package_dir, chirps_path)
    report_text = clean_html_text(read_text(package_dir, report_path))

    arrival_lags = extract_arrival_lags(report_text)
    gdacs_anchor = gdacs_clock_anchor(gdacs)
    origin = datetime.fromisoformat(gdacs_anchor["origin_utc"])

    windows = {
        area: clock_window(origin, values["min"], values["max"])
        for area, values in arrival_lags.items()
    }
    lag_span_min = arrival_lags["sri_lanka"]["max"] - arrival_lags["northern_sumatra"]["min"]
    gpm_mean_mm = round(float(gpm["stats"]["gpm_event_precip_mm_mean"]), 3)
    gpm_max_mm = round(float(gpm["stats"]["gpm_event_precip_mm_max"]), 3)
    chirps_mean_mm = round(float(chirps["stats"]["chirps_event_precip_mm_mean"]), 3)

    all_report_windows_present = len(arrival_lags) == 3
    label = (
        "tsunami_timing_ledger_consistent"
        if all_report_windows_present
        and gdacs_anchor["alert"] == "Red"
        and gdacs_anchor["magnitude"] >= 8.0
        and gpm_mean_mm < 1.0
        else "timing_ledger_incomplete"
    )

    primary_gt = {
        "answer": label,
        "origin_utc": gdacs_anchor["origin_utc"],
        "sumatra_arrival_utc": windows["northern_sumatra"].split("/")[0],
        "thailand_window_utc": windows["thailand"],
        "sri_lanka_window_utc": windows["sri_lanka"],
        "lag_span_min": lag_span_min,
        "gpm_mean_mm": gpm_mean_mm,
        "catalog_counts": {
            "eq_features": gdacs_anchor["eq_count"],
            "fl_features": gdacs_anchor["fl_count"],
            "main_eq_magnitude": gdacs_anchor["magnitude"],
            "main_eq_alert": gdacs_anchor["alert"],
        },
    }

    computed_gt = {
        "schema_version": "1.0",
        "event_id": PACKAGE_ID,
        "task_id": TASK_ID,
        "task_type": "numeric",
        "target_family": "tsunami_arrival_window_reconstruction_ledger",
        "evaluation_mode": "deterministic",
        "difficulty_level": "L3",
        "primary_gt": primary_gt,
        "formulas": {
            "arrival_clock_window": "GDACS origin UTC plus report lag bounds in minutes",
            "lag_span_min": "Sri Lanka latest lag minus northern Sumatra earliest lag",
            "consistency_label": "all three report windows present and Red M>=8 GDACS EQ and GPM mean < 1 mm",
        },
        "source_values": {
            "event_name": metadata["event_name"],
            "hazard_family": metadata["hazard_family"],
            "event_window": anchor["temporal_window"],
            "arrival_lags_min": arrival_lags,
            "lag_extraction_notes": {
                "northern_sumatra": "Parsed numeric minutes from the report phrase.",
                "thailand": "Parsed the report phrase 'an hour and a half to two hours' as 90-120 minutes.",
                "sri_lanka": "Parsed the report phrase 'two to three hours' as 120-180 minutes.",
            },
            "gdacs_anchor": gdacs_anchor,
            "precipitation_mm": {
                "gpm_mean": gpm_mean_mm,
                "gpm_max": gpm_max_mm,
                "chirps_mean": chirps_mean_mm,
            },
        },
        "numeric_tolerances": {
            "lag_span_min": {"value": lag_span_min, "tolerance": 0},
            "gpm_mean_mm": {"value": gpm_mean_mm, "tolerance": 0.001},
            "main_eq_magnitude": {"value": gdacs_anchor["magnitude"], "tolerance": 0.0},
        },
        "rubric": {
            "total_points": 20,
            "criteria": [
                {
                    "name": "GDACS clock anchor",
                    "points": 4,
                    "description": "Uses the Red Indonesia earthquake entry, origin 2004-12-26T00:58:50, magnitude 8.5, and reports 5 EQ plus 1 FL GDACS features.",
                },
                {
                    "name": "Report lag extraction",
                    "points": 4,
                    "description": "Parses the three stated report lag bounds from text: northern Sumatra 30 minutes, Thailand 90-120 minutes, and Sri Lanka 120-180 minutes.",
                },
                {
                    "name": "UTC window reconstruction",
                    "points": 4,
                    "description": "Adds the lag bounds to the origin time and returns the three UTC windows with seconds preserved.",
                },
                {
                    "name": "Threshold ledger",
                    "points": 4,
                    "description": "Computes lag_span_min = 150 and rounds GPM mean precipitation to 0.214 mm while applying the <1 mm threshold.",
                },
                {
                    "name": "Compact final JSON",
                    "points": 4,
                    "description": "Returns the deterministic label and requested fields while limiting conclusions to computed timing fields.",
                },
            ],
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": [
                metadata_path,
                anchor_path,
                report_path,
                gdacs_path,
                gpm_path,
                chirps_path,
            ],
        },
    }

    attach_reasoning_depth(computed_gt)

    with (task_dir / "computed_gt.json").open("w", encoding="utf-8") as handle:
        json.dump(computed_gt, handle, indent=2, sort_keys=True)
        handle.write("\n")


if __name__ == "__main__":
    main()
